import sys

def max_product(arr):
    n = len(arr)
    max_prod = 1
    for i in range(n):
        if arr[i] != 9:
            arr[i] += 1
            break
        else:
            arr[i] = 0
    for i in range(n):
        max_prod *= arr[i]
    return max_prod

